# Average pooling custom CUDA operator
avgpool_kernel_source = """
__global__ void avgpool_kernel(const float* input, const int k_h, const int k_w,
                                const int stride_h, const int stride_w,
                                const int pad_h, const int pad_w,
                                float* output, int batch_size, int channels,
                                int H_in, int W_in) {
    // Compute global output coordinates
    int out_h = blockIdx.y * blockDim.y + threadIdx.y;
    int out_w = blockIdx.x * blockDim.x + threadIdx.x;

    const int H_out = (H_in - k_h) / stride_h + 1;
    const int W_out = (W_in - k_w) / stride_w + 1;

    if (out_h >= H_out || out_w >= W_out) return;

    float sum = 0.0f;
    for (int di = -pad_h; di <= pad_h; ++di) {
        for (int dj = -pad_w; dj <= pad_w; ++dj) {
            int ih = out_h * stride_h + di + pad_h;
            int iw = out_w * stride_w + dj + pad_w;
            if (ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                // Linear index for input element: batch*channels*H*W + c*H_out*out_h*out_w? 
                // For simplicity we just add to a temporary per-output sum using atomicAdd.
            }
        }
    }
    float count = k_h * k_w;
    output[out_h * channels * H_in * W_in + out_w * channels * H_in * W_in] = sum / count;
}

torch::Tensor average_pool_cuda(torch::Tensor x, int kernel_size,
                                int stride=None, int padding=0) {
    auto size = x.numel();
    const int k_h = kernel_size;
    const int k_w = kernel_size;
    if (stride is not None) {
        const int s_h = stride;
        const int s_w = stride;
    } else {
        const int s_h = k_h;
        const int s_w = k_w;
    }
    const int pad_h = padding;
    const int pad_w = padding;

    // Output dimensions
    if (stride is not None) {
        const int H_out = (x.size(2) - k_h) / s_h + 1;
        const int W_out = (x.size(3) - k_w) / s_w + 1;
    } else {
        const int H_out = (x.size(2) - k_h) / k_h + 1;
        const int W_out = (x.size(3) - k_w) / k_w + 1;
    }

    auto out_shape = list(x.shape);
    if (stride is not None):
        out_shape[1:] = [out_shape[1] // s_h, out_shape[2] // s_w]
    else:
        out_shape[1:] = [x.size(1) // k_h, x.size(2) // k_w]

    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks_h = (out_shape[0] + block_size - 1) / block_size;
    const int num_blocks_w = (out_shape[2] + block_size - 1) / block_size;

    avgpool_kernel<<<num_blocks_h, block_size, num_blocks_w, block_size>>>(x.data_ptr<float>(), k_h, k_w,
                                                                   s_h, s_w, pad_h, pad_w, out.data_ptr<float()>, x.size(0), x.size(1),
                                                                   out_shape[0], out_shape[2]);

    return out;
}
